const isAppLanguage = (value:unknown):value is AppLanguage => value==='en'||value==='hi'||value==='kn';
const languageFor = (role:Role) => { const saved=read<Record<string,unknown>|null>(keyFor('session'),null)||{}; const stored=saved.role===role ? saved.language : read<unknown>(keyFor(`${role}-language`),'en'); return isAppLanguage(stored)?stored:'en'; };
const saveLanguage = (role:Role, language:AppLanguage) => { write(keyFor(`${role}-language`),language); const saved=read<AccountSession|null>(keyFor('session'),null); if(saved?.role===role)write(keyFor('session'),{...saved,language}); window.dispatchEvent(new CustomEvent('rigdesk-language',{detail:language})); };
const isAppTheme = (value:unknown):value is AppTheme => value==='light'||value==='dark';
const themeFor = (role:Role) => { const saved=read<Record<string,unknown>|null>(keyFor('session'),null)||{}; const stored=saved.role===role ? saved.theme : read<unknown>(keyFor(`${role}-theme`),'light'); return isAppTheme(stored)?stored:'light'; };
const saveTheme = (role:Role, theme:AppTheme) => { write(keyFor(`${role}-theme`),theme); const saved=read<AccountSession|null>(keyFor('session'),null); if(saved?.role===role)write(keyFor('session'),{...saved,theme}); };
