const translatePhrase=(english:string,language:AppLanguage)=>{if(language==='en')return english;const common=interfaceText(english,language);if(common)return common;const map=language==='kn'?kannadaUi:hindiUi;if(map[english])return map[english];if(english.startsWith('Good morning,'))return `${language==='kn'?'ಶುಭೋದಯ':'सुप्रभात'},${english.slice('Good morning,'.length)}`;const listingMatch=english.match(/^(.+) listing (RLX-[A-Z]+-\d+)$/);if(listingMatch)return `${map[listingMatch[1]]||listingMatch[1]} ${language==='kn'?'ಪಟ್ಟಿ':'सूची'} ${listingMatch[2]}`;const bookingParts=english.split(' · ');if(/^[\d,]+ ft planned$|^[\d,]+ km route$|^\d+h$|^flat-fee survey$/.test(bookingParts[0])){const first=bookingParts[0].replace('ft planned',language==='kn'?'ಅಡಿ ಯೋಜನೆ':'फीट योजना').replace('km route',language==='kn'?'ಕಿಮೀ ಮಾರ್ಗ':'किमी मार्ग').replace(/^(\d+)h$/,language==='kn'?'$1 ಗಂಟೆ':'$1 घंटे');return [map[first]||first,...bookingParts.slice(1).map(part=>{const units=part.match(/^(\d+) units$/);if(units)return language==='kn'?`${units[1]} ಯಂತ್ರಗಳು`:`${units[1]} इकाइयां`;const starts=part.match(/^starts (.+)$/);if(starts)return language==='kn'?`${starts[1]}ಕ್ಕೆ ಆರಂಭ`:`${starts[1]} से शुरू`;return map[part]||part})].join(' · ')}const availableMatch=english.match(/^(\d+) available$/);if(availableMatch)return language==='kn'?`${availableMatch[1]} ಲಭ್ಯ`:`${availableMatch[1]} उपलब्ध`;const bidMatch=english.match(/^(\d+) bids · (project|consignment) total$/);if(bidMatch)return language==='kn'?`${bidMatch[1]} ಬಿಡ್‌ಗಳು · ${bidMatch[2]==='project'?'ಯೋಜನೆ':'ಸಾಗಣೆ'} ಒಟ್ಟು`:`${bidMatch[1]} बोलियां · ${bidMatch[2]==='project'?'परियोजना':'खेप'} कुल`;const timeMatch=english.match(/^(\d+)h (\d+)m left$/);if(timeMatch)return language==='kn'?`${timeMatch[1]} ಗಂಟೆ ${timeMatch[2]} ನಿಮಿಷ ಬಾಕಿ`:`${timeMatch[1]} घंटा ${timeMatch[2]} मिनट बाकी`;return english;};
const applyTranslations=(language:AppLanguage)=>{const root=document.getElementById('root');if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode as Text;const parent=node.parentElement;if(!parent||parent.closest('script,style,svg,[data-localized]'))continue;const current=node.nodeValue||'';if(!originalText.has(node))originalText.set(node,current);else if(appliedText.has(node)&&current!==appliedText.get(node)&&current!==originalText.get(node))originalText.set(node,current);const source=originalText.get(node)||'';const trimmed=source.trim();const translated=translatePhrase(trimmed,language);const output=trimmed?source.replace(trimmed,translated):source;if(node.nodeValue!==output)node.nodeValue=output;appliedText.set(node,output)}root.querySelectorAll<HTMLElement>('[placeholder],[title],[aria-label]').forEach(element=>{let originals=originalAttributes.get(element);if(!originals){originals={};(['placeholder','title','aria-label'] as const).forEach(attribute=>{const value=element.getAttribute(attribute);if(value)originals![attribute]=value});originalAttributes.set(element,originals)}Object.entries(originals).forEach(([attribute,value])=>element.getAttribute(attribute)!==translatePhrase(value,language)&&element.setAttribute(attribute,translatePhrase(value,language)))})};
const observeTranslations=(language:AppLanguage)=>{applyTranslations(language);const root=document.getElementById('root');if(!root)return()=>{};let scheduled=false;const observer=new MutationObserver(()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;applyTranslations(language)})});observer.observe(root,{childList:true,characterData:true,subtree:true});return()=>observer.disconnect();};
